    headline: "青森から、ロボット・腹腔鏡・移植をつなぎ、肝胆膵外科の次世代を育てる。",
    description: `■ 医局の紹介
弘前大学 消化器外科学講座は、消化器外科、小児外科、肝胆膵・移植外科など、幅広い外科領域を担う教室です。

なかでも肝胆膵グループは、肝癌、胆管癌、膵癌といった悪性腫瘍を中心に、急性胆嚢炎、腹部外傷、末期肝疾患に対する生体肝移植まで、多様な疾患に対応しています。高難度手術、低侵襲手術、移植医療を組み合わせながら、青森県の高度外科医療と若手外科医育成を支えています。

■ DX・テクノロジーの取り組み
【Robotic & Endoscopic HBP Surgery】
弘前大学 消化器外科学講座では、肝胆膵領域において腹腔鏡手術やロボット支援下手術などの低侵襲手術に取り組んでいます。

ロボット支援下手術では、鮮明な3D画像と操作性の高いロボット鉗子を用いることで、より精密な手術を目指しています。同施設では、ロボット手術認定プロクターが在籍し、ロボットによる膵切除術および肝切除術を行っています。

単なるロボット導入ではなく、肝胆膵領域の高難度手術に対して、腹腔鏡・ロボット手術の適応を広げている点が特徴です。

【Advanced HBP Surgery & Transplant Care】
肝胆膵領域では、進行癌に対する根治性を追求し、多臓器合併切除や血行再建などの高難度手術にも取り組んでいます。大腸癌肝転移に対する肝切除、膵切除、胆道手術など、幅広い肝胆膵疾患に対応しており、2024年の肝胆膵グループ手術件数は214例とされています。

また、生体肝移植にも取り組み、肝胆膵手術と移植医療を組み合わせた高度専門診療を行っています。

【Surgical Education & Specialist Training】
弘前大学の肝胆膵グループは、日本肝胆膵外科学会が定める高度技能専門医修練施設（A）に認定されており、高度技能指導医・専門医が常時在籍しています。

ロボット支援手術や腹腔鏡手術は、手術手技の高度化だけでなく、若手外科医の教育にも重要な役割を持ちます。高精細な3D画像を共有しながら手術を行うことで、解剖理解、剥離層の把握、鉗子操作の習得などを視覚的に学びやすくなります。手術経験を個人の技に閉じず、専門医育成と次世代外科医教育へつなげている点を、外科教育テクノロジーとして取り組んでいます。

■ 実績・スタッツ
導入・活用技術： ロボット支援下手術、腹腔鏡手術、鮮明な3D画像、ロボット鉗子
確認できる体制： ロボット手術認定プロクター在籍
施設認定： 日本肝胆膵外科学会 高度技能専門医修練施設（A）
確認できる実績： 2024年 肝胆膵グループ手術件数214例
主な領域： 肝癌、胆管癌、膵癌、急性胆嚢炎、腹部外傷、生体肝移植、大腸癌肝転移
DX要素： 3D視野、ロボット鉗子、腹腔鏡手術、専門医教育、技術継承`,
