    tags: ["ctDNA", "MASLD/MASH", "ロボット支援手術", "内視鏡外科", "トランスレーショナルリサーチ"],
    headline: "切るだけでは終わらない。ctDNA、代謝、ロボットで外科医療を研究から進化させる。",
    description: `■ 医局の紹介
岩手医科大学 外科学講座は、上部・下部消化管外科、肝胆膵外科、乳腺外科、内分泌外科、小児外科に及ぶ広い領域の診療・研究を行う講座です。

同講座は、臨床現場で生じた疑問を基礎研究・臨床研究につなげ、成果を世界へ発信できる国際性豊かな外科医の育成を目指しています。消化器外科領域では、手術技術だけでなく、ctDNA、バイオマーカー、代謝改善、化学療法感受性など、治療方針決定や個別化医療につながる研究要素が確認できます。

■ DX・テクノロジーの取り組み
【Robotic & Endoscopic Surgery】
岩手医科大学 外科学講座では、消化器外科領域において腹腔鏡・内視鏡外科、ロボット支援手術を含む低侵襲手術の活用を進めています。

【ctDNA, Biomarkers & Precision Oncology】
同講座では、切除不能肝胆道がん治療におけるctDNA動態の観察研究、大腸癌患者におけるctDNA治療ナビゲーションシステムの基盤構築など、多様な研究テーマに取り組んでいます。

外科DXの観点では、ctDNAやバイオマーカー研究は、手術だけではなく、術前・術後治療、再発リスク評価、個別化治療へつながる重要なテクノロジーです。ロボット手術だけでなく、分子レベルの情報を治療戦略へ接続する外科研究として取り組んでいます。

【Metabolic Surgery & Translational Research】
同講座では、MASLD/MASHに対する減量・代謝改善手術の改善機序に関する研究にも取り組んでいます。

肥満、代謝異常、肝疾患、消化器外科を横断する研究は、手術成績や長期予後を支える重要な領域です。外科医療のテクノロジーを、手術室の中だけに限定せず、代謝・栄養・予後・バイオマーカーまで含めたトランスレーショナルリサーチとして進めています。

■ 実績・スタッツ
主な領域： 上部消化管、下部消化管、肝胆膵、乳腺、内分泌、小児外科
導入・活用技術： ロボット支援手術、内視鏡外科、腹腔鏡手術
研究領域： MASLD/MASH、ctDNA、乳癌術後再発バイオマーカー
DX要素： ctDNA治療ナビゲーション、バイオマーカー研究、代謝改善手術、低侵襲手術教育`,
