    headline: "ロボットで精密に、内視鏡と協働し、重粒子線と連携する。山形発の集学的外科。",
    description: `■ 医局の紹介
山形大学 外科学第一講座は、消化器疾患、乳がん、甲状腺がん、一般外科疾患を幅広く扱う講座です。

上部消化管、下部消化管、肝胆膵、乳腺の4診療グループ体制を構築し、消化器内科、腫瘍内科、放射線治療科、形成外科などと密に連携しながら診療を行っています。

年間約700件の消化器・一般・乳腺外科領域の手術を担当し、ロボット支援手術、腹腔鏡手術、集学的治療、重粒子線治療との連携を組み合わせた治療戦略に取り組んでいます。

■ DX・テクノロジーの取り組み
【Robotic & Minimally Invasive GI Surgery】
山形大学 外科学第一講座では、2020年3月に胃切除、同年8月に直腸切除、2022年3月に食道切除のロボット支援消化器手術を開始し、100例以上のロボット支援消化器手術を実施したと紹介されています。

下部消化管領域では、ロボット支援手術の強みを活かし、超低位前方切除、経肛門的直腸間膜切除（TaTME）、内肛門括約筋切除（ISR）などの術式に取り組んでいます。ロボット支援手術を、単なる機器導入ではなく、骨盤深部の機能温存、低侵襲化、若手教育に活用する技術として取り組んでいます。

【Endoscopic Collaboration & Hybrid Surgery】
山形大学では、GISTなどの粘膜下腫瘍に対して、消化器内科と連携し、LECSやD-LECSなどの腹腔鏡内視鏡合同手術にも取り組んでいます。

外科と内視鏡の境界領域であるLECS/D-LECSは、内視鏡診断・治療と腹腔鏡手術を組み合わせるハイブリッド治療です。ロボット手術だけでなく、内視鏡・腹腔鏡・外科が協働するテクノロジーとして取り組んでいます。

【Pancreatic Cancer & Heavy Ion Collaboration】
肝胆膵領域では、難治高度進行癌に注力し、化学療法や放射線療法と手術を組み合わせた集学的外科治療に取り組んでいます。

膵癌治療では「切除可能でも術前治療、切除不能でも治療奏効後のConversion手術を」という方針が示されており、浸潤性膵管癌切除症例数は2020年17例、2021年22例、2022年26例、2023年37例と増加しています。さらに、重粒子線照射後のConversion手術も1年間で8例実施しており、重粒子線施設直結の総合病院にある外科として、新しいエビデンス創出にも取り組んでいます。

■ 実績・スタッツ
確認できる実績： 年間約700件の消化器・一般・乳腺外科領域の手術
確認できる実績： ロボット支援消化器手術100例以上
ロボット手術開始： 2020年3月 胃切除、2020年8月 直腸切除、2022年3月 食道切除
DX要素： ロボット支援手術、TaTME、ISR、LECS、D-LECS、腹腔鏡手術、重粒子線連携
膵癌治療： 浸潤性膵管癌切除症例数 2020年17例、2021年22例、2022年26例、2023年37例
重粒子線連携： 重粒子線照射後のConversion手術 1年間で8例
主な領域： 食道、胃、大腸、肝胆膵、乳腺、甲状腺、一般外科`,
