    tags: ["4専門チーム制", "肝胆膵・移植", "がんゲノム医療", "直腸癌治療", "機能温存手術"],
    latestActivity: "上部消化管、下部消化管、肝胆膵・移植、乳腺内分泌代謝の4専門チーム制で、機能温存、移植、がんゲノム医療を推進",
    headline: "新潟の第一外科は、消化管・肝胆膵・移植をチームでつなぎ、がん治療を進化させる。",
    description: `■ 医局の紹介
新潟大学 消化器・一般外科（第一外科）は、上部消化管、下部消化管、肝胆膵・移植、乳腺・内分泌・代謝の4つの専門チームで診療・研究を行う医局です。

消化管と肝胆膵を一つの医局として運営しながら、それぞれの専門チームが臓器別の専門性を発揮し、連携して治療方針を検討します。4専門チームが一体となることで、多臓器にわたる疾患や集学的治療においても、横断的な視点で対応できる診療基盤を形成しています。

■ DX・テクノロジーの取り組み
【Four-Team Surgical Platform】
新潟大学 消化器・一般外科（第一外科）では、所属医師を上部消化管、下部消化管、肝胆膵・移植、乳腺・内分泌・代謝の4つの専門チームに分け、診療・研究を行っています。

この体制は、臓器別の専門性を維持しながら、消化器外科全体として治療方針を検討できる診療基盤です。4専門チーム制を、症例検討、術前画像評価、手術適応、薬物療法、移植医療をつなぐチーム医療プラットフォームとして取り組んでいます。

【Colorectal Genomics & Advanced Pelvic Surgery】
下部消化管チームでは、大腸癌、直腸癌、炎症性腸疾患、骨盤内悪性腫瘍、遺伝性大腸癌に対する診療・研究を行っています。

特に、リンチ症候群などの遺伝性大腸癌、がんゲノム医療、大腸癌の遺伝子変異と薬物療法、直腸癌の肛門温存手術とリンパ節郭清などが研究テーマとして紹介されています。手術だけではなく、ゲノム情報、薬物療法、機能温存、拡大手術を組み合わせて下部消化管外科として取り組んでいます。

【HBP & Transplant Surgical Care】
肝胆膵チームでは、肝臓、胆道、膵臓、脾臓、門脈にわたる外科診療と研究を行っています。

悪性疾患から良性疾患、膵・肝移植まで幅広く担当しており、術前画像評価、移植医療、周術期管理、薬物療法を組み合わせた肝胆膵・移植領域の総合治療として取り組んでいます。

■ 実績・スタッツ
正式名称： 新潟大学 消化器・一般外科（第一外科）
体制： 上部消化管、下部消化管、肝胆膵・移植、乳腺・内分泌・代謝の4専門チーム
主な領域： 食道、胃、大腸、直腸、肝臓、胆道、膵臓、脾臓、門脈、移植
DX要素： 専門チーム制、がんゲノム医療、遺伝性大腸癌、機能温存手術、術前画像評価、移植医療`,
