    tags: ["消化管がん", "集学的治療", "腫瘍免疫", "栄養", "がん微小環境"],
    latestActivity: "食道癌・胃癌・大腸癌を中心に、がん予防、新規診断、集学的治療、腫瘍免疫・栄養・微小環境研究を推進",
