    description: `■ 医局の紹介
京都大学大学院医学研究科 肝胆膵・移植外科学は、肝疾患、胆道疾患、膵臓疾患、内分泌腫瘍、大腸癌肝転移、肝移植などを対象とする分野です。

京都大学外科では、管腔臓器は消化管外科が担当し、肝胆膵領域は肝胆膵・移植外科が担当すると整理されています。肝胆膵疾患を対象に、手術と癌の集学的治療を行い、他院で切除不能と診断された進行癌に対しても高度な技術による最善の治療を提供すると説明されています。

■ DX・テクノロジーの取り組み
【Disease-Specific HBP Unit System】
京都大学 肝胆膵・移植外科では、肝疾患、胆道疾患、膵臓疾患、内分泌腫瘍、大腸癌肝転移のそれぞれについて、各診療科からの専門医で構成されるユニットで治療方針をディスカッションしていると紹介されています。

このユニット診療は、症例情報、画像診断、病理、腫瘍内科、放射線科、消化器内科、外科をつなぐ治療方針決定プラットフォームとして機能しています。

【Transplant Team Care】
肝移植では、移植外科医、内科医、麻酔科医、集中治療部医師、感染制御部医師、看護師、移植コーディネーター、理学療法士、栄養療法士、薬剤師らがチーム一丸となって周術期管理を行うと紹介されています。

肝移植を手術単独ではなく、術前評価、集中治療、感染制御、栄養管理、リハビリ、薬剤管理、移植コーディネーションを統合する多職種医療インフラとして表現します。

【Advanced HBP Surgery & Multimodal Oncology】
京都大学大学院医学研究科 肝胆膵・移植外科学では、肝胆膵疾患を対象に、手術と癌の集学的治療を行っていると紹介されています。

他院で切除不能と診断された進行癌に対しても、高度な技術による最善の治療を提供すると説明されており、高難度手術、薬物療法、画像診断、病理、ユニット診療を組み合わせた高難度がん治療として取り組んでいます。

■ 実績・スタッツ
正式名称： 京都大学大学院医学研究科 肝胆膵・移植外科学
主な領域： 肝疾患、胆道疾患、膵臓疾患、内分泌腫瘍、大腸癌肝転移、肝移植
診療体制： 疾患別ユニット、消化器内科、放射線科、腫瘍内科、病理診断科との連携
移植医療： 移植外科医、内科医、麻酔科医、集中治療部、感染制御、看護師、移植コーディネーター、理学療法士、栄養療法士、薬剤師
DX要素： ユニット診療、治療方針決定、多職種周術期管理、集学的治療、高難度手術`,
