    description: `■ 医局の紹介
東京科学大学 肝胆膵外科学は、肝臓、胆道、膵臓、脾臓の悪性腫瘍や炎症性疾患などに対して、外科治療を中心とした総合的診療を行う教室です。

ロボット手術の有無だけに焦点を当てず、PRRT、低侵襲膵切除、低侵襲肝切除、肝細胞癌に対する切除可能性分類など、治療選択・術式選択・低侵襲化を支えるテクノロジーを軸に診療を展開しています。

■ DX・テクノロジーの取り組み
【Treatment Decision Platform】
東京科学大学病院 肝胆膵外科では、肝細胞癌の腫瘍学的切除可能性分類（Expert Consensus 2023）の提唱を主導し、これを取り入れて手術と薬物療法を組み合わせた治療を行っています。

肝胆膵領域では、腫瘍の進行度、肝機能、血管・胆管との位置関係、全身状態を踏まえ、手術適応や術式を慎重に判断する必要があります。切除可能性分類は、単なる診断ではなく、治療方針決定を支えるデータ・意思決定レイヤーとして機能しています。

【PRRT & Precision HBP Oncology】
同科では、膵神経内分泌腫瘍などに対するペプチド受容体核医学内用療法（PRRT）を行っています。

PRRTは、膵神経内分泌腫瘍などに対する核医学治療として、外科治療だけではない肝胆膵領域の治療選択肢を広げる技術です。手術、核医学、薬物療法、低侵襲手術を組み合わせる精密治療として取り組んでいます。

【Minimally Invasive HBP Surgery】
東京科学大学病院 肝胆膵外科では、低侵襲膵切除術、低侵襲肝切除術が特色ある治療として紹介されています。

低侵襲膵切除では、腹腔鏡手術やロボット手術などを患者の状態や腫瘍の広がりに応じて個別に判断しています。低侵襲肝切除についても、患者の体への負担を抑えつつ、治療効果と安全性の両立を目指す治療として取り組んでいます。

■ 実績・スタッツ
主な領域： 肝臓がん（原発性、転移性）、膵臓がん（神経内分泌腫瘍、IPMNを含む）、胆管がん、胆のうがん、胆石症など
導入・活用技術： PRRT、低侵襲膵切除、低侵襲肝切除、腹腔鏡手術、ロボット手術
DX要素： 切除可能性分類、治療方針決定、低侵襲手術適応判断、核医学治療`,
