    description: `■ 医局の紹介
東京慈恵会医科大学 外科学講座は、上部消化管外科、下部消化管外科、肝胆膵外科、呼吸器外科、乳腺・甲状腺・内分泌外科、血管外科、小児外科などを含む外科学講座です。

このページでは、消化器外科領域である上部消化管、下部消化管、肝胆膵外科を中心に紹介しつつ、外科学講座全体としての横断的な診療・教育・研究基盤を表現します。

■ DX・テクノロジーの取り組み
【Department-Wide Surgical Platform】
東京慈恵会医科大学 外科学講座は、複数の診療部・疾患グループを内包する大きな外科学講座として運用されています。

臓器別の専門性を保ちながら、外科全体で人材育成、研究、教育、症例経験を共有するプラットフォームとして機能しています。

【HBP Advanced Surgery & Transplant Care】
慈恵医大の肝胆膵外科では、肝胆膵外科高度技能専門医制度のA認定施設、生体肝移植、腹腔鏡手術、低侵襲手術への取り組みが確認できます。

肝胆膵領域では、短期間で的確な診断をつけ、早期に必要な治療を開始し、なるべく短い入院期間で社会復帰を目指すと説明されています。肝胆膵外科を、画像診断、術式選択、低侵襲手術、移植医療、周術期管理をつなぐ高度専門診療として取り組んでいます。

【Comprehensive Multidisciplinary Surgery】
慈恵医大の肝胆膵外科では、腫瘍血液内科、内視鏡科、栄養サポートチームなどと連携し、包括的診療を行うことが紹介されています。

外科学講座を、手術単独ではなく、内視鏡、薬物療法、栄養管理、チーム医療、教育を接続する総合外科プラットフォームとして取り組んでいます。

■ 実績・スタッツ
組織体制： 上部消化管外科、下部消化管外科、肝胆膵外科などを含む外科学講座


肝胆膵領域： 肝胆膵外科高度技能専門医制度 A認定施設、生体肝移植、腹腔鏡手術
連携領域： 腫瘍血液内科、内視鏡科、栄養サポートチーム
DX要素： 講座横断型教育、低侵襲手術、術式選択、包括的診療、チーム医療`,
