    tags: ["手術手技マニュアル", "トレーニングシステム", "術前シミュレーション", "内視鏡外科", "患者個別リハーサル"],
    latestActivity: "全臓器領域での内視鏡外科、教室独自の手術手技マニュアル、トレーニングシステム、肝胆膵術前シミュレーションを推進",
    headline: "手術を標準化し、訓練し、リハーサルする。昭和医科大学の消化器外科は「仕組み」で進化する。",
    description: `■ 医局の紹介
昭和医科大学 外科学講座 消化器一般外科学部門は、食道、胃、大腸、肝胆膵、ヘルニア、腎移植など、幅広い消化器・一般外科領域を担う部門です。

同部門は、内視鏡外科を教室の基軸テーマとして掲げ、腹腔鏡・胸腔鏡手術を全臓器領域で展開しています。さらに、教室独自の手術手技マニュアルとトレーニングシステムを確立し、肝胆膵外科では術前シミュレーションによる患者個別リハーサルを必須としています。

■ DX・テクノロジーの取り組み
【Surgical Manual & Training System】
昭和医科大学 外科学講座 消化器一般外科学部門では、安全な腹腔鏡手術を提供するために、全ての臓器領域において教室独自の手術手技マニュアルが確立・運用されています。

さらに、手術手技取得のためのトレーニングシステムも確立されていると紹介されています。個人の経験に依存しやすい手術技術を、標準化・可視化・教育する仕組みとして、重要なDX要素として取り組んでいます。

【Patient-Specific Preoperative Simulation】
肝胆膵外科領域では、術前シミュレーションによる患者個別リハーサルを必須としていると紹介されています。

肝胆膵手術では、血管、胆管、膵管、腫瘍の位置関係を術前に精密に把握することが不可欠です。患者個別リハーサルを、術前画像評価、手術計画、リスク評価、チーム共有を支える手術インフラとして取り組んでいます。

【Endoscopic Surgery Across All Organs】
同部門では、全ての臓器領域における内視鏡外科、つまり腹腔鏡・胸腔鏡手術を教室の基軸テーマとして実施しています。

胃癌、大腸癌、肝臓手術、胆膵手術、胆石症、急性虫垂炎、ヘルニアなど、幅広い領域で鏡視下手術を展開しており、映像・標準化・教育・患者負担軽減をつなぐ外科プラットフォームとして取り組んでいます。

■ 実績・スタッツ
主な領域： 食道、胃、大腸、肝胆膵、胆石症、虫垂炎、ヘルニア、腎移植
導入・活用技術： 腹腔鏡手術、胸腔鏡手術、ロボット支援手術、術前シミュレーション
教育インフラ： 教室独自の手術手技マニュアル、手術手技取得トレーニングシステム
肝胆膵領域： 患者個別リハーサル、高度技能専門医修練施設A認定、血管再建を含む高難度手術
DX要素： 手術標準化、トレーニング、術前シミュレーション、鏡視下映像、患者個別手術計画`,
