    description: `■ 医局の紹介
東京医科大学 消化器・小児外科学分野は、食道、胃、大腸、肝胆膵、小児外科を包括する分野です。

公式サイトでは、ロボット支援下胃切除、ロボット支援下肝切除、ロボット支援下膵切除、ロボット支援下大腸切除、ロボット支援胆道拡張手術など、複数領域にわたるロボット支援手術の取り組みが紹介されています。

■ DX・テクノロジーの取り組み
【Cross-Organ Robotic Surgery Platform】
東京医科大学 消化器・小児外科学分野では、胃、肝臓、膵臓、大腸、小児胆道など、複数領域にロボット支援手術を展開しています。

ロボット支援下胃切除、肝切除、膵切除、大腸切除、胆道拡張手術がそれぞれ専門領域として紹介されており、消化器外科と小児外科を横断する手術支援プラットフォームとして取り組んでいます。

【Expert-Guided HBP Endoscopic Surgery】
肝胆膵領域では、ロボット支援下肝切除、ロボット支援下膵切除が紹介されています。

膵切除では、膵頭十二指腸切除術、膵体尾部切除術、膵腫瘍核出術などにおいて内視鏡外科手術が保険収載されており、高度な技術を要するため一部施設で行われているとされています。同分野では、肝胆膵外科手術および内視鏡外科手術の熟練したエキスパートにより手術を行うと紹介されています。

【Robotic Surgery as Education & Technical Dissemination】
東京医科大学の特徴は、ロボット支援手術を一つの臓器に限定せず、消化器・小児外科の複数領域に横断展開している点です。

ロボット支援手術を、専門グループごとの単発の技術ではなく、食道、胃、大腸、肝胆膵、小児外科を横断する教育・適応判断・技術共有の基盤として取り組んでいます。

■ 実績・スタッツ
主な領域： 食道癌、胃癌、大腸癌、肝癌、胆道癌、膵腫瘍、膵癌、小児外科、胆道拡張症
導入・活用技術： ロボット支援下胃切除、ロボット支援下肝切除、ロボット支援下膵切除、ロボット支援下大腸切除、ロボット支援胆道拡張手術
肝胆膵領域： 肝切除、膵頭十二指腸切除、膵体尾部切除、膵腫瘍核出術
DX要素： 複数領域へのロボット横断展開、手術教育、適応判断、技術共有、内視鏡外科手術`,
