    latestActivity: "肝胆膵、大腸・肛門、食道・胃の領域別専門性を活かし、術前症例カンファレンス、M&M、キャンサーボード、光工学研究を通じて診療と研究を接続",
    headline: "手術だけでなく、症例を検討し、光で見極め、チームで治療を設計する。",
    description: `■ 医局の紹介
東邦大学医学部 外科学講座 一般・消化器外科学分野は、消化器外科、小児外科、乳腺・内分泌外科を含む外科学講座の中で、消化器外科領域を担う分野です。

消化器外科では、肝胆膵外科、大腸・肛門外科、食道・胃外科の領域別に専門性を活かしながら診療を行い、横の連携を図りながらチームで診療・研究に取り組んでいます。

■ DX・テクノロジーの取り組み
【Conference-Based Surgical Governance】
東邦大学医学部 外科学講座 一般・消化器外科学分野では、毎週月曜日に消化器外科、小児外科、乳腺・内分泌外科、総合診療外科が集まり、朝は術前症例、夕方にはMortality & Morbidityについてのカンファレンスを行い、症例を詳細に検討しています。

これは、個々の医師の経験だけに頼るのではなく、症例情報をチームで共有し、治療方針や合併症リスクを検討する診療プロセスのインフラとして取り組んでいます。

【Cancer Board & Multidisciplinary Decision-Making】
各領域では、毎週定期的にキャンサーボードが開催され、消化器系悪性腫瘍を中心に、消化器内科医、腫瘍専門内科医、放射線科医とともに治療方針を検討しています。

手術単独ではなく、外科、消化器内科、腫瘍内科、放射線科が連携する治療方針決定プラットフォームとして取り組んでいます。

【Optical Engineering & HBP Innovation】
肝胆膵外科の研究では、最先端の低侵襲性肝胆膵手術、腹腔鏡下肝切除の安全性と有効性の検証、光工学を利用した肝腫瘍の診断と肝切除術式の開発などが紹介されています。

光工学、低侵襲手術、術式開発、QOL評価、感染制御、機能温存肝・膵切除など、肝胆膵外科を支える研究開発レイヤーとして取り組んでいます。

■ 実績・スタッツ
正式名称： 東邦大学医学部 外科学講座 一般・消化器外科学分野
診療領域： 肝胆膵外科、大腸・肛門外科、食道・胃外科
診療プロセス： 術前症例カンファレンス、M&Mカンファレンス、キャンサーボード
連携領域： 消化器内科、腫瘍専門内科、放射線科、小児外科、乳腺・内分泌外科、総合診療外科
研究要素： 光工学を利用した肝腫瘍診断、肝切除術式開発、低侵襲肝胆膵手術、QOL評価
DX要素： カンファレンス、キャンサーボード、光工学、治療方針決定、領域横断チーム医療`,
