    latestActivity: "上部消化管・下部消化管・肝胆膵の3診療科グループ体制で、内視鏡治療、腹腔鏡・ロボット支援下手術、シミュレーター教育を推進",
    headline: "内視鏡も、腹腔鏡も、ロボットも。3診療科グループで育てる総合消化器外科。",
    description: `■ 医局の紹介
杏林大学 消化器・一般外科学教室は、上部消化管外科、下部消化管外科、肝胆膵外科の3診療科グループに分かれ、消化器外科領域の診療・教育・研究を行う教室です。

    治療対象は悪性腫瘍を中心としつつ、胆石症、ヘルニア、炎症性腸疾患などの良性疾患にも対応しています。開腹手術だけでなく、腹腔鏡下手術、ロボット支援下手術、内視鏡的切除も行っています。

■ DX・テクノロジーの取り組み
【Three - Group Surgical Platform】
杏林大学 消化器・一般外科学教室では、上部消化管外科、下部消化管外科、肝胆膵外科の3診療科グループに分かれて診療を行っています。

臓器別の専門性を持ちながら、消化器外科全体として幅広い疾患に対応する診療プラットフォームとして取り組んでいます。

【Endoscopic, Laparoscopic & Robotic Care】
同教室では、開腹手術だけでなく、腹腔鏡下手術、ロボット支援下手術、内視鏡的切除も行っており、3診療科合わせて年間800件前後の手術症例数で推移していると紹介されています。

医局サイトでは「外科医でありながら内視鏡もできる」ことを目指せる環境、低侵襲手術、集学的治療を学べる環境も紹介されています。内視鏡、腹腔鏡、ロボットを、患者ごとの治療選択肢を広げる外科基盤として取り組んでいます。

【Simulation & Bedside Learning】
杏林大学の教育では、系統講義、ベッドサイドラーニング、カンファレンス参加、手術参加、症例サマリー、レポート・プレゼンなどが紹介されています。

さらに、腹腔鏡下手術のシミュレーターを用いた手術トレーニングや、縫合結紮手技のトレーニングも行われています。手術手技を可視化・訓練・評価する教育インフラとして取り組んでいます。

■ 実績・スタッツ
正式名称： 杏林大学 消化器・一般外科学教室
診療体制： 上部消化管外科、下部消化管外科、肝胆膵外科の3診療科グループ
手術症例数： 3診療科合わせて年間800件前後
導入・活用技術： 内視鏡的切除、腹腔鏡下手術、ロボット支援下手術
教育要素： BSL、カンファレンス、手術参加、症例サマリー、プレゼン、腹腔鏡シミュレーター、縫合結紮トレーニング
DX要素： 内視鏡・腹腔鏡・ロボットの治療選択、シミュレーター教育、手術手技トレーニング、集学的治療`,
