    tags: ["ロボット支援縦隔鏡下食道切除", "ロボット胃がん手術", "腹腔鏡手術", "医療ビッグデータ解析", "若手外科医教育"],
    headline: "胸に傷をつけない食道手術へ。ロボット、腹腔鏡、医療データで胃食道外科を進化させる。",
    description: `■ 医局の紹介
東京大学 胃食道・乳腺内分泌外科は、東京大学大学院医学系研究科 消化管外科学・乳腺内分泌外科学として、胃食道外科領域と乳腺内分泌外科領域を担う医局です。

本紹介では、消化器外科領域である胃食道外科の取り組みを中心に紹介します。食道がん、胃がんに対する低侵襲手術、ロボット支援手術、腹腔鏡手術を軸に、患者に寄り添う医療と未来を担う外科医の育成を進めています。

また、乳腺内分泌外科領域では、約80万例を用いた医療ビッグデータ解析などの研究も紹介されており、手術だけでなくデータを活用した外科研究にも取り組んでいます。

■ DX・テクノロジーの取り組み
【Robotic Mediastinoscopic Esophagectomy】
東京大学 胃食道・乳腺内分泌外科では、胃食道外科のトピックスとして「胸に傷をつけない」ロボット支援縦隔鏡下食道切除が紹介されています。

食道がん手術では、胸部・縦隔という深く狭い領域で、重要な血管や神経の近くを精密に操作する必要があります。ロボット支援縦隔鏡下食道切除は、胸を大きく開く従来手術とは異なり、低侵襲性と精密操作の両立を目指す外科テクノロジーとして取り組んでいます。

【Robotic & Laparoscopic Gastric Surgery】
同医局では、ロボット・腹腔鏡による胃がん低侵襲手術も紹介されています。

胃がん手術では、リンパ節郭清、再建、機能温存などを症例ごとに検討する必要があります。ロボット支援手術と腹腔鏡手術を組み合わせ、患者の身体的負担を抑えながら、根治性と安全性を追求する胃食道外科として取り組んでいます。

【Data-Driven Research & Surgical Education】
東京大学 胃食道・乳腺内分泌外科は、患者に寄り添う医療と未来を担う外科医の育成を掲げています。

胃食道外科の低侵襲手術に加え、乳腺内分泌外科領域では約80万例を用いた医療ビッグデータ解析も紹介されています。外科医療の進化を、手術室内の技術だけでなく、データ解析・臨床研究、若手外科医教育まで含めた取り組みとして進めています。

■ 実績・スタッツ
消化器領域： 胃食道外科
主な対象： 食道がん、胃がん、胃食道領域疾患
導入・活用技術： ロボット支援縦隔鏡下食道切除、ロボット胃がん手術、腹腔鏡胃がん手術
研究・データ要素： 約80万例を用いた医療ビッグデータ解析
教育要素： 未来を担う外科医の育成`,
