    name: "肝胆膵外科・人工臓器移植外科",
    tags: ["腹腔鏡・ロボット肝切除", "腹腔鏡・ロボット膵切除", "肝移植", "手術ナビゲーション", "医療機器開発"],
    headline: "肝胆膵の難問に、ロボット、移植、ナビゲーション、AIで挑む。",
    description: `■ 医局の紹介
東京大学 肝胆膵外科・人工臓器移植外科は、肝胆膵外科と人工臓器・移植外科を一体で担う医局です。

肝胆膵外科では、肝がん、膵がん、胆管がん、胆嚢がんなどの悪性腫瘍を中心に、胆石症、膵・胆管合流異常症などの良性疾患も含めて広く肝胆膵疾患の外科治療を行っています。治療方針はエビデンスに基づき、カンファレンスで決定されています。

人工臓器・移植外科では、末期肝疾患に対する生体肝移植および脳死肝移植を手掛けています。緻密な管理と各診療科を含めたチーム連携医療を特徴とし、肝胆膵外科と移植医療を接続する高度専門領域として診療にあたっています。

■ DX・テクノロジーの取り組み
【Laparoscopic & Robotic HBP Surgery】
東京大学 肝胆膵外科・人工臓器移植外科では、肝切除・膵切除などにおいて腹腔鏡手術やロボット支援手術を活用しています。

肝胆膵領域では、血管や胆管、膵管の走行を正確に把握しながら、複雑な解剖構造の中で精密な操作を行う必要があります。腹腔鏡・ロボット手術は、低侵襲性と精密操作を両立するテクノロジーとして活用されています。

【Transplant, Team Care & Evidence-Based Conference】
人工臓器・移植外科では、末期肝疾患に対する生体肝移植および脳死肝移植を手掛けています。

肝移植では、手術技術だけでなく、術前評価、ドナー・レシピエント管理、周術期管理、免疫抑制、退院後フォローなど、チーム連携が不可欠です。肝胆膵外科でも、治療方針をエビデンスに基づきカンファレンスで決定していることが紹介されています。

【Navigation, Device Development & AI Research】
公式スタッフ紹介では、肝胆膵領域の悪性腫瘍、医療機器開発・手術ナビゲーション、人工知能、肝移植を専門分野とする医師が在籍していることが確認できます。

医療機器開発、手術ナビゲーション、人工知能研究を、肝胆膵外科・移植医療の精度向上に向けた研究開発領域として取り組んでいます。

■ 実績・スタッツ
主な領域： 肝がん、膵がん、胆管がん、胆嚢がん、転移性肝がん、膵嚢胞性腫瘍、膵神経内分泌腫瘍、胆石症、肝移植
導入・活用技術： 腹腔鏡肝切除、ロボット肝切除、腹腔鏡膵切除、ロボット膵切除、手術ナビゲーション
移植領域： 生体肝移植、脳死肝移植
研究開発： 医療機器開発、手術ナビゲーション、人工知能
診療体制： エビデンスに基づくカンファレンス、肝胆膵外科4チーム体制、チーム連携医療`,
